/* Review only: renders the Death Star product patterns in system.html with the product's own helpers. */
(() => {
  const DS = window.DS; if (!DS) return;
  const { D, ui, icon, esc } = DS;
  const c = D.cById.marchetti;
  const S = {
    trust: () => ['verified', 'single', 'stale', 'disputed'].map(k => ui.trust(k)).join(''),
    classes: () => ['A', 'B', 'C', 'D'].map(k => ui.cls(k)).join('') + ['A', 'B'].map(k => ui.cls(k, true)).join(''),
    chips: () => ui.rankChip(c) + ui.bldChip(D.pById[c.pid]) + `<span class="ds-chip" data-tone="outline"><span class="ds-dot" data-tone="active"></span>Contacted</span><span class="ds-chip">Tier 1 · Hot</span><span class="ds-chip" data-tone="danger">${icon('warning-diamond')}Asked not to be contacted</span>${ui.dncList(D.dncList[0])}<span class="ds-filter-chip">${icon('funnel-simple')}Lower East Side</span><span class="ds-outtag" data-o="Interested">Interested</span><span class="ds-outtag" data-o="Callback">Callback</span><span class="ds-sev" data-sev="Critical">Critical</span><span class="ds-sev" data-sev="Strong">Strong</span>`,
    shell: () => `<div class="sys-shellbar"><span class="ds-wordmark" style="flex:none">Death Star</span><nav class="ds-crumbs" aria-label="Example breadcrumb"><a href="#patterns">Database</a>${icon('caret-right')}<span aria-current="page">Daniel Marchetti</span></nav><button type="button" class="ds-search-trigger" style="width:15rem">${icon('magnifying-glass')}<span>Search contacts, properties, BBL</span><kbd>⌘K</kbd></button><button type="button" class="ds-ask" aria-pressed="false">${icon('sparkle')}Ask Brain<span class="ds-ask__dot"></span></button><button type="button" class="ds-ask" aria-pressed="true">${icon('sparkle')}Ask Brain</button></div><div class="sys-shellnav"><a class="ds-nav" aria-current="page" href="#patterns">${icon('house')}<span>Home</span></a><a class="ds-nav" href="#patterns">${icon('squares-four')}<span>Dashboard</span></a><span class="ds-nav-group" role="presentation"><span>Channels</span>${icon('caret-down')}</span><a class="ds-nav" role="link" tabindex="0" aria-disabled="true" data-tip="${DS.OFF}">${icon('envelope-simple')}<span>Email</span><span class="ds-nav__badge">4</span></a></div>`,
    why: () => `<section class="ds-why"><div class="ds-why__head">${icon('sparkle')}<h2>Why now</h2>${ui.trust('verified')}<span class="ds-grow"></span><span class="ds-meta">Updated 2d ago</span></div><p class="ds-why__text">${esc(c.whyFull)}</p><div class="ds-why__actions">${ui.btn({ label: 'Next: Call (212) 555-0147', ic: 'phone', variant: 'subtle', shape: 'pill' })}<span class="ds-grow"></span>${ui.btn({ label: 'Why this?', variant: 'outline' })}${ui.btn({ label: 'Ask Brain', ic: 'sparkle', variant: 'outline' })}</div></section>`,
    evidence: () => `<div class="ds-stack" data-gap="2">${D.evidence(c).slice(0, 3).concat([D.evidence(c)[5]]).map(([l, v, m, k]) => `<div class="ds-evidence"><div class="ds-row__body"><span><span class="font-medium">${esc(l)}</span><span class="muted"> · ${esc(v)}</span></span><span class="ds-meta">${esc(m)}</span></div>${ui.trust(k)}${k === 'disputed' ? '<span></span>' : ui.btn({ label: 'Flag as wrong', variant: 'ghost', size: 'sm' })}</div>`).join('')}</div>`,
    callnext: () => ['marchetti', 'feld'].map((id, i) => ui.callRow(D.cById[id], i ? `<span class="ds-called">${icon('check')}</span>` : `<button type="button" class="button button--icon" data-variant="outline" aria-label="Call ${esc(D.cById[id].name)}">${icon('phone')}</button>`, !!i)).join(''),
    pulse: () => `<div class="ds-pulse">${[['Meetings this week', 'handshake', '3', 'with owners', 0, '+2 vs. last week (1)', 'up'], ['Calls today', 'phone', '6', 'of 40', 0.15, '+2 vs. yesterday', 'up'], ['Follow-ups due', 'clock', '1', 'today', 0, '2 overdue', 'warn']].map(([l, i, v, of, r, d, t], n) => `<a class="ds-pulse__cell"${n ? '' : ' data-lead'} href="#patterns"><span class="ds-pulse__label"><span class="ds-tile-icon" data-tone="tint">${icon(i)}</span>${l}</span><span class="ds-pulse__value"><b>${v}</b><span class="ds-meta">${of}</span></span>${ui.progress(r, l, { thin: true, fill: true })}<span class="ds-delta" data-tone="${t}">${icon(t === 'up' ? 'arrow-up-right' : 'warning-circle')}${d}</span></a>`).join('')}</div>`,
    chart: () => { const t = D.tiles[0]; return `<div class="ds-card" data-pad="lg">${ui.bars(t.vals, t.labels, { max: t.max, goal: t.goal, zero: t.zero, aria: t.title })}</div>`; },
    live: () => `<div class="ds-livebar" style="position:static;border-radius:var(--radius-lg)"><span class="ds-livebar__dot"></span><span class="font-medium">On a call with Daniel Marchetti</span><span class="ds-livebar__num">(212) 555-0147</span><span class="ds-grow"></span><span class="ds-livebar__time">1:14</span>${ui.btn({ label: 'End call', ic: 'phone-disconnect' })}</div><div class="ds-outcome" style="margin-top:var(--space-3)"><h2>Log the outcome</h2><div class="ds-stack" data-gap="2" role="radiogroup" aria-label="Example outcome"><div class="ds-outcome__opts">${DS.OUT.main.map(o => `<button type="button" class="ds-opt" role="radio" aria-checked="${o === 'Conversation'}">${o}</button>`).join('')}</div><div class="ds-outcome__quick"><span class="ds-meta">Not reached</span>${DS.OUT.quick.map(o => `<button type="button" class="ds-quickopt" role="radio" aria-checked="false">${o}</button>`).join('')}</div></div><div class="ds-stack" data-gap="2"><span class="field__label">What came out of it</span><div class="ds-toolbar" style="gap:var(--space-1-5)">${[...DS.OUT.results, ['cb', 'Call back']].map(([k, l]) => `<button type="button" class="ds-pill-btn" role="checkbox" aria-checked="${k === 'meeting'}" aria-pressed="${k === 'meeting'}">${k === 'meeting' ? icon('check') : ''}${l}</button>`).join('')}</div></div><div class="ds-toolbar">${ui.btn({ label: 'Save outcome' })}${ui.btn({ label: 'Skip', variant: 'outline' })}</div></div>`,
    brain: () => `<div class="ds-brain" style="width:auto"><div class="ds-brain__head">${icon('sparkle')}<b>Brain</b></div><div class="ds-chat"><div class="ds-msg-user">Why now for Daniel Marchetti?</div><div class="ds-msg-bot"><div class="ds-msg-bot__text">${esc(c.whyFull)}</div><div class="ds-answer"><div style="display:flex;align-items:center;gap:var(--space-2)">${ui.cls('A')}<b class="ds-grow">Daniel Marchetti</b>${ui.trust('verified')}</div><div class="ds-toolbar">${ui.btn({ label: 'Call', ic: 'phone', size: 'sm' })}${ui.btn({ label: 'Open record', size: 'sm', variant: 'outline' })}</div></div></div><div class="ds-think">${['Finding the owner', 'Reading the evidence', 'Writing the why now'].map((t, i) => `<span class="ds-think__step" data-state="${['done', 'now', 'todo'][i]}">${icon(['check-circle', 'circle-notch', 'circle'][i])}${t}</span>`).join('')}</div></div>${DS.composer(false)}</div>`,
    events: () => `<div class="ds-toolbar" style="align-items:stretch">${[['mtg', 'Lunch · Grace Okafor', '12 PM – 1 PM'], ['call', 'Calls · LES maturities', '1:30 PM – 3 PM'], ['tour', 'Tour · 41 Ludlow St', '9:30 AM – 10:30 AM'], ['bov', 'BOV pitch · 64 Essex St', '11 AM – 12 PM']].map(([k, t, tm], i) => `<button type="button" class="ds-ev" data-cal="${k}" aria-pressed="${i === 1}" style="position:relative;width:11rem;height:3rem"><b><span class="ds-ev-dot"></span>${t}</b><span>${tm}</span></button>`).join('')}</div><div style="max-width:17rem;margin-top:var(--space-3)"><a class="ds-conv" href="#patterns"><span style="display:flex;align-items:center;gap:var(--space-2)">${ui.cls('B')}<b class="ds-grow">Ruth Adler</b></span><span style="color:var(--fg-secondary)">Open to a pricing opinion on 64 Essex St</span><span class="ds-conv__foot"><span class="ds-outtag" data-o="Interested">Interested</span><span class="ds-meta">Send comps Fri</span></span></a></div>`,
    report: () => {
      const st = (l, v, extra, cmp, tool = '') => `<div class="ds-stat"><span class="ds-stat__label"><span class="ds-grow">${esc(l)}</span>${tool}</span><span class="ds-stat__value"><b>${esc(v)}</b>${extra || ''}</span>${cmp ? `<span class="ds-stat__cmp">${cmp.map(([k, n]) => `<span><span class="ds-meta">${k}</span><span class="ds-stat__cmpv">${n}</span></span>`).join('')}</span>` : ''}</div>`;
      const tiles = `<div class="ds-statrow">${st('Calls', '6', '', [['Previous day', 33], ['This week', 112]], ui.iconBtn({ ic: 'list-bullets', aria: 'See every call', disabled: true }))}${st('First meetings', '4', `<span class="ds-delta" data-tone="up">${icon('arrow-up')}+33%</span>`, null, ui.iconBtn({ ic: 'plus', aria: 'Log one', disabled: true }))}${st('Listings', '1', `<span class="ds-delta" data-tone="warn">${icon('arrow-down')}−50%</span>`)}${st('Proposals', '2', `<span class="ds-delta" data-tone="flat">${icon('minus')}0%</span>`)}</div>`;
      const cov = `<div class="ds-covgrid">${[['10038', 1, 41], ['10013', 2, 58], ['10002', 26, 184]].map(([z, h, r]) => { const p = h / r * 100; return `<button type="button" class="ds-cov" aria-disabled="true"${p < 5 ? ' data-thin' : ''}><span class="ds-cov__top"><b>${z}</b><span class="ds-cov__p">${Math.round(p)}%</span></span>${ui.progress(p / 15, z, { tone: p < 5 ? 'warn' : 'accent', fill: true })}<span class="ds-meta">${h} of ${r} touched</span></button>`; }).join('')}</div>`;
      const funnel = `<div class="ds-funnel">${[['Sent', 2400, '100%'], ['Opened', 1056, '44%'], ['Clicked', 144, '6%']].map(([l, v, p]) => `<div class="ds-funnel__row"><span>${l}</span><span class="ds-hbar__track"><span data-tone="accent" style="width:${Math.round(v / 24)}%"></span></span><span class="ds-funnel__n">${v.toLocaleString('en-US')}</span><span class="ds-funnel__p">${p}</span></div>`).join('')}</div>`;
      const table = `<div class="ds-dtable-wrap"><table class="ds-dtable" aria-label="Example data table"><thead><tr><th scope="col">Channel</th><th scope="col" data-n>Sessions</th><th scope="col"></th><th scope="col" data-n>Conv.</th></tr></thead><tbody>${[['Direct', 2040, 5], ['Email · Constant Contact', 1053, 4], ['Paid', 197, 0]].map(([c, s, v]) => `<tr><td>${c}<span class="ds-dtable__sub">Last 30 days</span></td><td data-n>${s.toLocaleString('en-US')}</td><td><span class="ds-dtable__bar"><span style="width:${Math.round(s / 20.4)}%"></span></span></td><td data-n>${v ? `<b>${v}</b>` : '<span class="muted">0</span>'}</td></tr>`).join('')}</tbody></table></div>`;
      const inq = `<div class="ds-card" data-pad="none"><div class="ds-inq" data-new><span class="ds-tile-icon">${icon('envelope-simple')}</span><div class="ds-inq__body"><span class="ds-inq__who"><b>Priya Venkataraman</b><span class="ds-meta">Contact form</span><span class="badge" data-status="warning">Awaiting follow-up</span></span><p>Could you send the rent roll?</p><span class="ds-meta">41 Ludlow St · Sep 29, 4:12 PM</span></div><div class="ds-inq__acts">${ui.btn({ label: 'Reply', variant: 'outline', size: 'sm', disabled: true })}</div></div></div>`;
      return tiles + `<div class="ds-two"><div class="ds-card" data-pad="lg">${cov}</div><div class="ds-card" data-pad="lg">${funnel}</div></div><div class="ds-card" data-pad="lg">${table}</div>` + inq;
    },
    // Lists: the criteria builder. Editable chips, an offered chip, Add criteria, the live count and the two actions; static chips as Brain shows them.
    criteria: () => { const C = DS.crit, items = C.parse('cls:A;btype:fm;eng:Clicked 41 Ludlow St OM'), n = C.count(items);
      return `<section class="ds-builder" aria-label="Example criteria"><div class="ds-builder__bar"><a class="ds-crit-from" href="#patterns">${icon('caret-left')}From Reporting</a>${items.map((it, i) => ui.critChip(it, { editing: i === 1 })).join('')}${ui.critChip(C.parse('hood:Lower East Side')[0], { suggest: true })}<button type="button" class="ds-crit-addbtn">${icon('plus')}Add criteria</button></div>
        <section class="ds-crit-edit" aria-label="Example editor"><div class="ds-crit-edit__head">${icon('buildings')}<b>Building type</b><span class="ds-meta">Pick one or more · matches any of them</span><span class="ds-grow"></span><span class="ds-meta">${n} match</span>${ui.btn({ label: 'Done', variant: 'outline', size: 'sm' })}</div><div class="ds-toolbar" style="gap:var(--space-1-5)"><button type="button" class="ds-pill-btn" aria-pressed="true">Fully free market</button><button type="button" class="ds-pill-btn" aria-pressed="false">Rent stabilized</button><button type="button" class="ds-pill-btn" aria-pressed="false">Mixed</button></div></section>
        <div class="ds-builder__foot"><span class="ds-builder__count"><b class="num">${n}</b> owners match<span class="ds-meta"> · every criterion must match</span></span><span class="ds-grow"></span>${ui.btn({ label: 'Save as list', ic: 'list-bullets', variant: 'outline' })}${ui.btn({ label: 'Push to queue', ic: 'arrow-up-right' })}</div>
        <div class="ds-crit-done">${ui.approved('Queued for Phone · ' + n + ' owners')}</div></section>
        <div class="ds-toolbar" style="gap:var(--space-1-5)">${C.parse(D.brainList).map(it => ui.critChip(it, { static: true })).join('')}</div>
        <div class="ds-tolist-row">${ui.toList('eng:Clicked 41 Ludlow St OM', { q: 'from=reporting' })}${ui.toList('eng:Clicked 41 Ludlow St OM', { icon: true })}<span class="ds-meta">Turn into a list: a labelled button on cards, an icon on rows</span></div>`; },
    approvals: () => `<div class="ds-stack" data-gap="2">${ui.approval({ text: 'Save as <b>LES debt due 2026</b>?', yes: ['Save list'], no: ['Not now'] })}${ui.approval({ text: 'Remember this for <b>Okafor and similar family owners</b>?', yes: ['Approve'], no: ['Not now'] })}${ui.approved('Saved to Lists · LES debt due 2026')}</div>`,
    relationship: () => `<section class="ds-rel" aria-label="Example relationship"><div class="ds-rel__head">${icon('handshake')}<h2>Relationship</h2><span class="ds-chip" data-tone="outline">Warmth 64</span><span class="ds-meta">31 touches since 2014</span><span class="ds-grow"></span><span class="ds-teamchip">${icon('users')}Team knows this building</span></div>
      <div class="ds-rel__grid"><div class="ds-rel__col"><h3>The notes that matter</h3><div class="ds-rel__note"><p>Would only sell into a 1031 upstate; his wife wants out of managing tenants.</p><div class="ds-toolbar"><span class="ds-meta">Mar 12, 2019</span><a class="ds-link-btn" href="#patterns">Open in Activity${icon('caret-right')}</a></div></div><span class="ds-meta">Picked by Brain from 14 notes.</span></div>
        <div class="ds-rel__col"><h3>Who on the team knew them</h3><div class="ds-rel__who"><span class="avatar" data-size="sm">JS</span><span class="ds-row__body"><span class="font-medium">John Stewart</span><span class="ds-row__sub">Proposal 2004, Listing 2005, Sale 2006, BOV 2012 · 118 Ludlow St</span></span></div><h3>What they said</h3><p class="ds-rel__quote">“Talk to me after the summer. I’ll know where the refi lands.”</p></div></div></section>`,
    callprep: () => { const p = D.pById[c.pid]; return `<p class="ds-why__which"><span class="ds-meta">Which building</span><a href="#patterns">${esc(p.addr)}</a><span class="num">· ${p.score}</span></p><section class="ds-card ds-callprep" data-pad="all" style="margin-top:var(--space-3)"><div class="ds-two"><div class="ds-stack" data-gap="2"><div class="ds-callprep__h"><h3>Opener</h3><span class="ds-meta">In your voice · never a price</span></div>${DS.openerOf(c).slice(0, 2).map(l => `<p class="ds-callprep__line">${esc(l)}</p>`).join('')}</div><div class="ds-stack" data-gap="2"><div class="ds-callprep__h"><h3>Buyers who fit</h3><span class="ds-meta">For ${esc(p.addr)}</span></div>${D.buyersFor(p).slice(0, 3).map(b => `<div class="ds-callprep__buyer"><span class="font-medium">${esc(b.name)}</span><span class="ds-meta">${esc(b.box)} · ${esc(b.when)}</span></div>`).join('')}</div></div></section>`; },
    inbox: () => { const L = DS.apprList().filter(a => a.lane === 'email').slice(1, 4); return `<div class="ds-inbox__group" style="max-width:26rem"><div class="ds-inbox__lane">${icon('envelope-simple')}<b>Email</b><span class="ds-meta">${L.length}</span><span class="ds-grow"></span>${ui.btn({ label: 'Approve all 2', size: 'sm', variant: 'ghost' })}</div>${L.map((a, i) => `<button type="button" class="ds-inbox__row" aria-current="${i === 0}"><span class="ds-row__body"><span class="font-medium ds-ellipsis">${esc(a.c.name + ' · ' + a.p.addr)}</span><span class="ds-meta ds-inbox__why">${esc(a.why)}</span></span>${a.blocked ? `<span class="badge" data-status="danger">${icon('warning-diamond')}Blocked</span>` : ''}</button>`).join('')}</div><p style="margin-top:var(--space-3)">${ui.waiting('a2', 'Draft waiting for your click')}</p>`; },
    teach: () => ui.teach('attack-plan'),
    change: () => ui.changeNote('ranking'),
    fix: () => { const L = DS.cleanList(), row = x => `<div class="ds-fix"${x.flag ? ' data-flag' : ''}>${x.flag ? '<span class="ds-fix__pick" aria-hidden="true"></span>' : `<label class="choice ds-fix__pick"><input type="checkbox"><span class="sr-only">Select</span></label>`}<div class="ds-fix__body"><div class="ds-fix__top"><b>${esc(x.field)}</b><span class="ds-fix__who"><a href="#patterns">${esc(x.c ? x.c.name : x.p.addr)}</a></span>${x.flag ? `<span class="badge" data-status="warning">${icon('flag')}Left for you</span>` : ''}</div><p class="ds-fix__change"><span class="ds-fix__from">${esc(x.from)}</span>${icon('arrow-right')}<span class="ds-fix__to">${esc(x.to)}</span></p><p class="ds-fix__why">${esc(x.why)}</p><p class="ds-fix__src">${esc(x.src)} · ${x.conf}% confidence</p></div><div class="ds-fix__acts">${ui.btn({ label: 'Approve', ic: 'check', size: 'sm', variant: 'outline' })}${ui.btn({ label: 'Reject', size: 'sm', variant: 'ghost' })}${ui.btn({ label: 'Defer', size: 'sm', variant: 'ghost' })}</div></div>`;
      return `<div class="ds-stack" data-gap="3">${ui.tabs([['contacts', 'Contacts'], ['properties', 'Properties'], ['cleaning', 'Cleaning', false, 11]], 'cleaning', 'Example tabs with a count')}<div class="ds-fixlist" style="max-width:52rem">${row(L.find(x => x.id === 'o1'))}${row(L.find(x => x.id === 'o2'))}</div></div>`; },
    lift: () => ui.lift(c),
    team: () => `<div class="ds-card" data-pad="all"><div class="ds-teamlist">${D.teamOf('p118').slice(0, 3).map(e => `<div class="ds-teamrow"><span class="ds-teamrow__year">${e.year}</span><span class="ds-row__body"><span><span class="font-medium">${esc(e.type)}</span><span class="muted"> · ${esc(e.who)}</span></span><span class="ds-teamrow__doc">${icon('file-text')}${esc(e.doc)}</span></span><span class="ds-off-link" aria-disabled="true">${icon('arrow-square-out')}Open</span></div>`).join('')}</div></div>`,
    // Proactive Brain: a suggested list (reason, chips, approval), a lesson in Learning Mode, a headline story, the drop zone.
    proactive: () => { const x = D.suggested[0], n = DS.crit.count(DS.crit.parse(x.crit));
      return `<section class="ds-bsugg" aria-label="Example Brain suggests" style="max-width:19rem"><div class="ds-bsugg__head"><span class="ds-bot-av">${icon('sparkle')}</span><span class="ds-row__body"><b>Brain suggests</b><span class="ds-meta">3 lists from last week’s outreach</span></span>${icon('caret-up')}</div><div class="ds-bsugg__body"><ul class="ds-bsugg__list"><li class="ds-bsugg__row"><a class="ds-bsugg__main" href="#patterns"><span class="ds-bsugg__n num">${n}</span><span class="ds-row__body"><span class="ds-bsugg__name">${esc(x.name)}</span><span class="ds-bsugg__hint">${esc(x.tag + ' · ' + x.hint)}</span></span></a><span class="ds-bsugg__acts"><button type="button" class="ds-bsugg__save">Save list</button>${ui.iconBtn({ ic: 'x', aria: 'Dismiss' })}</span></li></ul><span class="ds-bsugg__foot">Nothing is saved or queued until you approve it.</span></div></section>
        <div class="ds-card" data-pad="all"><div class="ds-lesson">${icon('book-open')}<span class="ds-row__body"><span class="font-medium">${esc(D.okaforLesson[0])}</span><span class="ds-row__sub">${esc(D.okaforLesson[1])} · approved by Thomas W., today</span></span>${ui.btn({ label: 'Forget', variant: 'ghost', size: 'sm', disabled: true })}</div></div>
        <div class="ds-dropzone">${icon('paperclip')}<b>Drop files here</b><span class="ds-meta">PDFs, spreadsheets and notes</span></div>`; },
    story: () => { const h = D.headlines[0], items = DS.crit.parse(h.crit), l = D.listings[2];
      return `<article class="ds-news" style="max-width:24rem"><span class="ds-news__art" aria-hidden="true">${DS.streetArt({ id: 'sys-' + h.id, label: h.t, stories: 5, units: 18 })}</span><div class="ds-news__body"><span class="ds-news__meta"><span class="ds-news__tag">${esc(h.tag)}</span><span>${esc(h.src)} · ${esc(DS.ago(h.hours))}</span></span><h3>${esc(h.t)}</h3><p>${esc(h.sum)}</p><span class="ds-news__rel">${icon('users')}<b class="num">${DS.loc(DS.crit.count(items))}</b> owners in your lists</span><span class="ds-news__acts">${ui.btn({ label: 'Draft a post', ic: 'linkedin-logo', variant: 'outline', size: 'sm' })}${ui.toList(h.crit, { icon: true })}</span></div></article>
        <button type="button" class="ds-lcard" aria-pressed="true" style="max-width:16rem"><span class="ds-lcard__img" aria-hidden="true">${DS.streetArt({ id: 'sys-l', label: l.addr, ...l.art })}</span><span class="ds-lcard__body"><span class="ds-lcard__top"><b>${esc(l.addr)}</b><span class="badge" data-status="success">${esc(l.status)}</span></span><span class="ds-meta">East Village · 16 units · $8.2M</span><span class="ds-lcard__stats"><span><b>318</b> views</span><span><b>3</b> known</span><span><b>0</b> offers</span></span></span></button>
        <div class="ds-answer ds-post"><div class="ds-post__step"><span class="ds-step-num">3</span><b>Draft · LinkedIn</b></div><blockquote class="ds-draftpost">${esc(D.postDraft)}</blockquote></div>`; },
    illustration: () => { const p = D.pById.p118; return `<div class="ds-two" data-ratio="even"><div class="ds-facade" data-wide data-art>${DS.facade(p)}</div>${DS.mapTile(p)}</div>`; },
    app: () => {
      const tab = (l, ic, on) => `<a class="ds-tab" href="#app"${on ? ' aria-current="page"' : ''}>${icon(ic, on ? 'fill' : 'regular')}<span>${l}</span></a>`;
      const phone = body => `<div class="sys-appframe" data-shell="app"><div class="ds-appshell" style="height:auto;min-height:0">${body}</div></div>`;
      const s1 = phone(`<div class="ds-apage" style="padding-top:var(--space-4)">${ui.large('Good morning, Thomas', 'Wednesday, September 30')}
        <div class="ds-alist">${[['phone', 'Call Daniel Marchetti', '$9.4M loan due in June · Verified'], ['calendar-blank', '9:30 AM · Tour, 41 Ludlow St', 'Priya Venkataraman']].map(([ic, t, m]) => `<a class="ds-arow" data-lead href="#app"><span class="ds-arow__lead">${icon(ic)}</span><span class="ds-arow__body"><span class="ds-arow__title">${esc(t)}</span><span class="ds-arow__sub">${esc(m)}</span></span><span class="ds-arow__end">${icon('caret-right')}</span></a>`).join('')}</div>
        <div class="ds-atiles"><div class="ds-atile"><span class="ds-atile__label">${icon('phone')}Calls today</span><span class="ds-atile__value"><b>6</b><span class="ds-meta">of 40</span></span>${ui.progress(0.15, 'Calls', { thin: true, fill: true })}<span class="ds-atile__foot" data-tone="up">${icon('arrow-up-right')}+2 vs. yesterday</span></div><div class="ds-atile"><span class="ds-atile__label">${icon('chat-text')}Conversations</span><span class="ds-atile__value"><b>2</b><span class="ds-meta">of 5</span></span>${ui.progress(0.4, 'Conversations', { thin: true, fill: true })}<span class="ds-atile__foot">${icon('check')}On pace</span></div></div></div>
        <div class="ds-callslot"><div class="ds-callpill"><a class="ds-callpill__go" href="#app"><span class="ds-livebar__dot" aria-hidden="true"></span><span class="ds-callpill__name">Daniel Marchetti</span><span class="ds-callpill__time">1:14</span></a><button type="button" class="ds-callpill__end" aria-label="End call">${icon('phone-disconnect')}</button></div></div>
        <nav class="ds-tabbar" aria-label="Example tab bar" style="padding-bottom:var(--space-2)">${tab('Today', 'sun', true)}${tab('Brain', 'sparkle')}${tab('Database', 'database')}${tab('More', 'dots-three-circle')}</nav>`);
      const s2 = phone(`<div class="ds-apage" style="padding-top:var(--space-4)"><div class="ds-aid"><span class="ds-aid__av">DM</span><h1>Daniel Marchetti</h1>${ui.cls('A', true)}<span class="ds-aid__meta">Ludlow 118 Holdings LLC · Family owner</span></div>
        <div class="ds-qacts"><button type="button" class="ds-qact" data-primary>${icon('phone')}Call</button><button type="button" class="ds-qact">${icon('note')}Note</button><span class="ds-qact" aria-disabled="true">${icon('chat-text')}Text</span><span class="ds-qact" aria-disabled="true">${icon('envelope-simple')}Email</span></div>
        <section class="ds-callcard"><span class="ds-meta">On a call · (212) 555-0147</span><span class="ds-callcard__time">1:14</span>${ui.btn({ label: 'End call', ic: 'phone-disconnect' })}</section>
        <div class="ds-daystrip">${[['Mon', 28], ['Tue', 29], ['Wed', 30, 1], ['Thu', 1], ['Fri', 2], ['Sat', 3, 0, 1], ['Sun', 4, 0, 1]].map(([d, n, t, w]) => `<button type="button" class="ds-daystrip__d" aria-pressed="${!!t}"${t ? ' data-today' : ''}${w ? ' data-weekend' : ''}><span>${d}</span><b>${n}</b></button>`).join('')}</div>
        <div class="ds-achips" style="margin:0;padding:0;flex-wrap:wrap"><button type="button" class="ds-fchip" aria-pressed="true">Class A${icon('caret-down')}</button><button type="button" class="ds-fchip">Trust${icon('caret-down')}</button><button type="button" class="ds-fchip" aria-pressed="true">${icon('check')}In territory</button></div></div>`);
      const s3 = phone(`<section class="ds-sheet" style="box-shadow:none;max-height:none;padding-bottom:0" aria-label="Example sheet"><span class="ds-sheet__grab" aria-hidden="true"></span><header class="ds-sheet__head"><h2>Log the outcome</h2>${ui.iconBtn({ ic: 'x', aria: 'Close' })}</header><div class="ds-sheet__body"><p class="ds-meta">Call lasted 2:14 · (212) 555-0147</p><div class="ds-sheet-sec"><h3>Outcome</h3><div class="ds-opts">${DS.OUT.main.slice(0, 2).map(o => `<button type="button" class="ds-optrow" role="radio" aria-checked="false"><span>${o}</span><span class="ds-optrow__mark">${icon('check')}</span></button>`).join('')}</div><div class="ds-achips" style="margin:0;padding:0;flex-wrap:wrap;align-items:center"><span class="ds-meta">Not reached</span>${DS.OUT.quick.map(o => `<button type="button" class="ds-fchip" role="radio" aria-checked="${o === 'No answer'}" aria-pressed="${o === 'No answer'}">${o === 'No answer' ? icon('check') : ''}${o}</button>`).join('')}</div></div></div><footer class="ds-sheet__foot">${ui.btn({ label: 'Skip', variant: 'outline' })}${ui.btn({ label: 'Save outcome' })}</footer></section>`);
      // Brain's chat history as the left drawer (the same list as the web column, DS.chatHistory).
      const s4 = phone(`<div style="position:relative;height:36rem;overflow:hidden"><div class="ds-drawer-scrim" style="position:absolute;z-index:0"></div><aside class="ds-history" data-drawer aria-label="Example chats drawer" style="padding-top:var(--space-2)">${DS.chatHistory(true)}</aside></div>`);
      return `<div class="sys-appgrid">${s1}${s2}${s3}${s4}</div>`;
    },
  };
  const draw = () => document.querySelectorAll('[data-sample]').forEach(el => { const f = S[el.dataset.sample]; if (f) el.innerHTML = f(); });
  draw();
})();
